(
    select(
        func.extract('month', Attendance.work_date).label('month'),
        func.extract('year', Attendance.work_date).label('year'),
        func.sum(Attendance.scheduled_minutes).label('scheduled_minutes'),
        func.sum(Attendance.worked_minutes).label('worked_minutes'),
        func.sum(Overtime.approved_minutes).label('approved_minutes') / 60.0
    )
    .select_from(Attendance)
    .outerjoin(Overtime, Attendance.employee_id == Overtime.employee_id)
    .where(
        or_(
            and_(func.extract('year', Attendance.work_date) == 2026, func.extract('month', Attendance.work_date).in_([1, 2, 3])),
            and_(func.extract('year', Attendance.work_date) == 2025, func.extract('month', Attendance.work_date).in_([1, 2, 3]))
        )
    )
    .group_by(func.extract('month', Attendance.work_date), func.extract('year', Attendance.work_date))
    .order_by(func.extract('year', Attendance.work_date), func.extract('month', Attendance.work_date))
)

