    description: total approved minutes of overtime; convert to hours by dividing by 60.0 when hours are requested so decimals are preserved
  - status: VARCHAR(32)
relationships:
  - employee: many-to-one -> Employee; relationship key: Overtime.employee_id -> Employee.id

